/** Existing audio synthesis consumes the same semantics as hearing and text. */
function worldAcousticSoundCue(event: WorldAcousticEvent): SoundCue {
  if (
    event.domain === "animal-contact"
    && event.semanticFamily === "rustle"
    && event.triggerEventId.startsWith("ecology-contact:")
    && event.sourceId.startsWith("ecology-aggregate-source:")
  ) return "rat-rustle";
  switch (event.semanticFamily) {
    case "splash":
    case "slosh":
      return "sweep";
    case "thud":
    case "clatter":
    case "crack":
      return "impact";
    case "scrape":
    case "rustle":
    case "skitter":
    case "creak":
      return "stumble";
    case "chorus":
      return "frog-chorus";
    case "vocalization":
    case "other":
      return "impact";
  }
}

interface CommittedAudioCue {
  readonly cue: SoundCue;
  readonly volume: number;
  readonly variantSeed: number;
  readonly pan?: number;
}

function committedAudioCueForSituatedExpression(
  expression: Parameters<typeof situatedExpressionAudioPresentation>[0],
  reception: Parameters<typeof situatedExpressionAudioPresentation>[1],
): CommittedAudioCue | null {
  const presentation = situatedExpressionAudioPresentation(expression, reception);
  if (presentation === null) return null;
  const cue: SoundCue = presentation.sound.kind === "legacy-cue"
    ? presentation.sound.cue
    : `vocalization-${presentation.sound.vocalization}`;
  return Object.freeze({
    cue,
    volume: presentation.volume,
    variantSeed: presentation.variantSeed,
    pan: presentation.pan,
  });
}

function runtimePerformanceNow(): number {
  try {
    const now = globalThis.performance?.now();
    if (Number.isFinite(now) && now >= 0) return now;
  } catch {
    // Telemetry must never become an authoritative runtime failure boundary.
  }
  try {
    const fallback = Date.now();
    if (Number.isFinite(fallback) && fallback >= 0) return fallback;
  } catch {
    // A hostile clock still cannot stop authoritative simulation work.
  }
  return 0;
}

function serializedSaveByteLength(value: string): number {
  // Count exact UTF-8 without allocating another save-sized byte buffer. This
  // probe runs only when profiling and, deliberately, after the timed snapshot.
  let bytes = 0;
  for (let index = 0; index < value.length; index += 1) {
    const codeUnit = value.charCodeAt(index);
    if (codeUnit <= 0x7f) {
      bytes += 1;
    } else if (codeUnit <= 0x7ff) {
      bytes += 2;
    } else if (
      codeUnit >= 0xd800
      && codeUnit <= 0xdbff
      && index + 1 < value.length
    ) {
      const trailing = value.charCodeAt(index + 1);
      if (trailing >= 0xdc00 && trailing <= 0xdfff) {
        bytes += 4;
        index += 1;
      } else {
        bytes += 3;
      }
    } else {
      bytes += 3;
    }
  }
  return bytes;
}

