function runtimeBio0Porter(economy: WorldView, actorId?: string): RuntimeBio0Porter {
  const startingSettlementId = economy.contracts.find(({ status }) => status === "offered")
    ?.originSettlementId ?? economy.settlements[0]?.id;
  const seedResidents = actorId === undefined && startingSettlementId !== undefined
    ? economy.residents.filter((resident) => (
        resident.location.kind === "settlement"
        && resident.location.settlementId === startingSettlementId
      ))
    : [];
  const residents = actorId === undefined
    ? [...(seedResidents.length > 0 ? seedResidents : economy.residents)].sort((left, right) => (
        left.identity.stableId < right.identity.stableId
          ? -1
          : left.identity.stableId > right.identity.stableId
            ? 1
            : left.id - right.id
      ))
    : economy.residents.filter(({ identity }) => identity.stableId === actorId);
  for (const resident of residents) {
    const address = livingActorAddressForResident(economy, resident);
    if (address?.species === "human") {
      return { resident, address: address as Bio0PorterAddress };
    }
  }
  throw new Error(actorId === undefined
    ? "BIO0 requires one existing compatibility resident"
    : "BIO0 porter no longer resolves through the compatibility resident owner");
}

function runtimeBio0DogGeneration(
  world: WorldState,
  resident: ResidentState,
): DogIdentityGenerationInput {
  return {
    seed: world.meta.rootSeed,
    originRegion: createRegionCoord(
      resident.identity.originRegion.x,
      resident.identity.originRegion.y,
    ),
    originNamespace: "regional",
    habitatClass: "coastal-lowland",
    habitatKey: BIO0_HABITAT_KEY,
    populationKey: BIO0_POPULATION_KEY,
    populationOrdinal: resident.identity.originActorOrdinal,
  };
}

function runtimeBio0FoodIds(
  world: WorldState,
  porterActorId: string,
): Readonly<{
  providerContainerId: string;
  receiverContainerId: string;
  sourceLotId: string;
}> {
  const identity = hashCanonical([
    "tideweft-bio0-runtime/1",
    world.meta.rootSeed,
    porterActorId,
  ]);
  return {
    providerContainerId: `bio0:porter-pack:${identity}`,
    receiverContainerId: `bio0:dog-contact-pack:${identity}`,
    sourceLotId: `bio0:dried-fish:${identity}`,
  };
}

function createRuntimeBio0Ecology(
  world: WorldState,
  economy: WorldView = createWorldView(world),
): Bio0EcologyState {
  const porter = runtimeBio0Porter(economy);
  const foodIds = runtimeBio0FoodIds(world, porter.address.actorId);
  const unitLoad = PROVISION_DEFINITIONS["dried-fish"].loadMilli;
  const porterFacing = headingToRadians(porter.address.heading);
  const dogOffsetX = Math.round(Math.cos(porterFacing) * WORLD_POSITION_UNITS_PER_TILE);
  const dogOffsetY = Math.round(Math.sin(porterFacing) * WORLD_POSITION_UNITS_PER_TILE);
  return createBio0Ecology({
    dogGeneration: runtimeBio0DogGeneration(world, porter.resident),
    // Seed the first causal web where the porter can actually perceive the
    // animal. This is a physical placement, not an injected cognition fact.
    dogPosition: translateWorldPosition(porter.address.position, dogOffsetX, dogOffsetY),
    porterAddress: porter.address,
    food: {
      providerContainerId: foodIds.providerContainerId,
      receiverContainerId: foodIds.receiverContainerId,
      lotId: foodIds.sourceLotId,
      provision: "dried-fish",
      quantity: BIO0_PROVISION_QUANTITY,
      providerCapacityMilliLoad: unitLoad * BIO0_PROVISION_QUANTITY,
      receiverCapacityMilliLoad: unitLoad,
      providerClosure: "open",
      materialState: { condition: FIXED_POINT, contamination: 0, decay: 0 },
    },
    tick: world.meta.completedTick,
  });
}

function canonicalRuntimeBio0Ecology(
  value: unknown,
  world: WorldState,
  economy: WorldView = createWorldView(world),
): Bio0EcologyState | null {
  const state = canonicalizeBio0EcologyState(value);
  if (state === null || state.tick !== world.meta.completedTick) return null;
  let porter: RuntimeBio0Porter;
  try {
    porter = runtimeBio0Porter(economy, state.porterAddress.actorId);
  } catch {
    return null;
  }
  const foodIds = runtimeBio0FoodIds(world, porter.address.actorId);
  if (
    stableStringify(porter.address) !== stableStringify(state.porterAddress)
    || state.dog.identity.stableId !== stableDogId(runtimeBio0DogGeneration(world, porter.resident))
    || state.foodSource.providerContainerId !== foodIds.providerContainerId
    || state.foodSource.receiverContainerId !== foodIds.receiverContainerId
    || state.foodSource.sourceLotId !== foodIds.sourceLotId
  ) return null;
  return state;
}

function createRuntimeCoreEcology(
  world: WorldState,
  bio0: Bio0EcologyState,
  economy: WorldView = createWorldView(world),
): CoreEcologyAggregatePatchState {
  const habitat = deriveRuntimeCoreEcologyHabitat(world, bio0, economy);
  const groups = createRuntimeCoreEcologyGroups(world, habitat);
  let patch = createCoreEcologyAggregatePatch({
    seed: world.meta.rootSeed,
    patchKey: CORE_ECOLOGY_PATCH_KEY,
    originRegion: habitat.originRegion,
    tick: world.meta.completedTick,
    derivation: { kind: "habitat-v11", habitat },
    groups,
    populations: habitat.populations
      .filter(({ populationUnits, representation }) => (
        populationUnits > 0
        && representation === "individual-representatives"
      ))
      .filter(({ species }) => coreEcologySpeciesCanOwnActorAddress(species))
      .map((population) => ({
        species: population.species,
        populationKey: population.populationKey,
        populationSize: population.populationUnits,
        members: population.allocations.map((allocation) => ({
          populationOrdinal: allocation.allocationOrdinal,
          representedUnits: allocation.representedUnits,
          position: allocation.position,
          materialization: "coarse" as const,
        })),
      })),
  });
  const initialMaterialization = setCoreEcologyMaterializationForWindow(
    patch,
    {
      origin: (() => {
        const regionOrigin = regionLocalToGlobalTile(habitat.originRegion, 0, 0);
        return {
          x: regionOrigin.x - Math.trunc((REGIONAL_TRAVEL_COLUMNS - WORLD_WIDTH) / 2),
          y: regionOrigin.y - Math.trunc((REGIONAL_TRAVEL_ROWS - WORLD_HEIGHT) / 2),
        };
      })(),
      terrain: { width: REGIONAL_TRAVEL_COLUMNS, height: REGIONAL_TRAVEL_ROWS },
    },
    world.meta.completedTick,
  );
  if (initialMaterialization === null) {
    throw new Error("Initial tidal-web materialization failed validation");
  }
  patch = initialMaterialization;
  const bearMember = patch.populations
    .find(({ species }) => species === "black-bear")
    ?.members[0];
  if (bearMember !== undefined) {
    const hungryBear = replaceCoreWildlifeActorPhysiology(bearMember.actor, {
      atTick: world.meta.completedTick,
      needs: { ...bearMember.actor.needs, hunger: Math.max(680_000, bearMember.actor.needs.hunger) },
      condition: bearMember.actor.condition,
    });
    patch = replaceCoreEcologyAggregatePatchActor(patch, hungryBear);
  }
  const tidal = stepCoreEcologyTidalTable(patch, {
    atTick: world.meta.completedTick,
  });
  if (tidal === null) throw new Error("Initial tidal ecology projection failed validation");
  const initialized = initializeRuntimeTidalActivityActor(
    tidal.patch,
    tidal.projection,
    world.meta.completedTick,
  );
  if (initialized === null) throw new Error("Initial tidal actor placement failed validation");
  const waterfowlInitialized = initializeRuntimeWaterfowlActivityActor(
    initialized,
    world.meta.completedTick,
    economy.weather,
  );
  if (waterfowlInitialized === null) {
    throw new Error("Initial waterfowl placement failed validation");
  }
  const tidalWebInitialized = initializeRuntimeTidalWebActivityActor(
    waterfowlInitialized,
    world.meta.completedTick,
  );
  if (tidalWebInitialized === null) {
    throw new Error("Initial tidal-web activity placement failed validation");
  }
  return tidalWebInitialized;
}

/**
 * Alpha-32 separates settlement-owned animals from the signed regional
 * wildlife ledger. This patch remains the authoritative home for livestock,
 * the settlement-edge rat population, and their physical custody records.
 */
function createRuntimeSettlementHomeCoreEcology(
  world: WorldState,
  bio0: Bio0EcologyState,
  economy: WorldView = createWorldView(world),
): CoreEcologyAggregatePatchState {
  return createCoreEcologySettlementHomePatch({
    seed: world.meta.rootSeed,
    habitat: deriveRuntimeCoreEcologyHabitat(world, bio0, economy),
    tick: world.meta.completedTick,
  });
}

function canonicalRuntimeSettlementHomeCoreEcology(
  value: unknown,
  world: WorldState,
  bio0: Bio0EcologyState,
  economy: WorldView = createWorldView(world),
): CoreEcologyAggregatePatchState | null {
  return canonicalCoreEcologySettlementHomePatch(value, {
    seed: world.meta.rootSeed,
    habitat: deriveRuntimeCoreEcologyHabitat(world, bio0, economy),
    completedTick: world.meta.completedTick,
  });
}

function createRuntimeRegionalEcologyState(
  world: WorldState,
  bio0: Bio0EcologyState,
  settlementHome: CoreEcologyAggregatePatchState,
  regionalView: WorldView,
  economy: WorldView = createWorldView(world),
): RegionalEcologyStateV6 {
  const root = createPristineRegionalEcologyRoot({
    rootSeed: world.meta.rootSeed,
    completedTick: world.meta.completedTick,
  });
  const activeRegions = regionalStorageRegionsInView(regionalView);
  const residents = deriveRuntimeRegionalResidentInputs(
    root,
    world.meta.rootSeed,
    activeRegions,
  );
  const state = createRegionalEcologyState({
    root,
    settlementHome: {
      sourceKey: settlementHome.patchKey,
      patch: settlementHome,
    },
    activeRegions,
    activeResidents: residents,
  });
  const canonicalBase = canonicalRuntimeRegionalEcologyStateV1(
    state,
    world,
    bio0,
    economy,
  );
  if (canonicalBase === null) {
    throw new Error("Initial regional ecology state failed its world binding");
  }
  const alpineWrapped = createFreshRegionalEcologyStateV2(
    canonicalBase,
    world.meta.rootSeed,
  );
  const polarWrapped = createFreshRegionalEcologyStateV3(
    alpineWrapped,
    world.meta.rootSeed,
  );
  const coldWrapped = createFreshRegionalEcologyStateV4(
    polarWrapped,
    world.meta.rootSeed,
  );
  const polarConsumerWrapped = createFreshRegionalEcologyStateV5(
    coldWrapped,
    world.meta.rootSeed,
  );
  const wrapped = createFreshRegionalEcologyStateV6(
    polarConsumerWrapped,
    world.meta.rootSeed,
  );
  const canonical = canonicalRuntimeRegionalEcologyState(
    wrapped,
    world,
    bio0,
    economy,
  );
  if (canonical === null) {
    throw new Error("Initial regional ecology v6 state failed its world binding");
  }
  return canonical;
}

function deriveRuntimeRegionalResidentInputs(
  root: RegionalEcologyRootV1,
  rootSeed: RootSeed,
  regions: readonly RegionCoord[],
): readonly RegionalEcologyActiveResidentInput[] {
  return Object.freeze(regions.flatMap((region) => {
    const patch = createCoreEcologyRegionalResidentPatchForRoot({
      seed: rootSeed,
      root,
      region,
    });
    return patch === null ? [] : [{
      kind: "regional-habitat" as const,
      sourceKey: patch.patchKey,
      patch,
    }];
  }));
}

/**
 * Reprojects the transient schedule destinations owned by one active regional
 * source. Settlement-home actors still authenticate against their embedded
 * frozen habitat; sparse regional and migration owners must present a current
 * root-bound receipt for every materialized activity actor.
 */
function runtimeCoreEcologyActivityAuthorityBundle(
  rootSeed: RootSeed,
  root: RegionalEcologyRootV1,
  sources: readonly RuntimeRegionalEcologyProjectedSource[],
  receiptCache: RuntimeCoreEcologyActivityAuthorityReceiptCache<
    CoreEcologyActivityAuthorityReceipt
  >,
  alpineSeedFingerprint: string,
): RuntimeCoreEcologyActivityAuthorityBundle | null {
  const sourceKeys: string[] = [];
  const requests: RuntimeCoreEcologyActivityAuthorityRequest<
    CoreEcologyActivityAuthorityReceipt
  >[] = [];
  for (const source of sources) {
    sourceKeys.push(source.sourceKey);
    const activityOwners = source.patch.populations
      .flatMap((population) => population.members
        .filter(({ actor, materialization }) => (
          materialization === "materialized"
          && coreEcologySpeciesHasBoundedActivityProjection(actor.identity.species)
        ))
        .map((member) => Object.freeze({
          actor: member.actor,
          member,
          population,
        })))
      .sort((left, right) => compareText(
        left.actor.identity.stableId,
        right.actor.identity.stableId,
      ));
    if (source.kind === "settlement-home") {
      if (!coreEcologyPatchHasBoundedActivityAuthority(source.patch)) return null;
      continue;
    }
    if (
      source.kind === "regional-polar-shore"
      || source.kind === "regional-cold-shore"
    ) {
      if (activityOwners.length > 0) return null;
      continue;
    }
    for (const { actor, member, population } of activityOwners) {
      const lineage = runtimeCoreEcologyActivityAuthorityLineage(
        root,
        source,
        actor.identity.stableId,
      );
      if (lineage === null) return null;
      const custody: RuntimeCoreEcologyActivityAuthorityCustody = Object.freeze({
        rootSeed,
        sourceKind: source.kind,
        sourceKey: source.sourceKey,
        sourceRegionX: source.patch.originRegion.x,
        sourceRegionY: source.patch.originRegion.y,
        derivationKind: source.patch.derivation.kind,
        lineageKey: lineage.lineageKey,
        actorId: actor.identity.stableId,
        species: actor.identity.species,
        populationKey: population.populationKey,
        populationOrdinal: member.populationOrdinal,
        representedUnits: member.representedUnits,
        alpineSeedFingerprint: source.kind === "regional-alpine"
          ? alpineSeedFingerprint
          : null,
        legacyCustodyKey: lineage.legacyCustodyKey,
      });
      requests.push(Object.freeze({
        sourceKey: source.sourceKey,
        custody,
        project: () => source.kind === "regional-breadth-v1"
          ? projectCoreEcologyBreadthActivityAuthority({
              rootSeed,
              patch: source.patch,
              actorId: actor.identity.stableId,
            })
          : source.kind === "regional-polar-consumer-v1"
          ? projectCoreEcologyPolarConsumerActivityAuthority({
              rootSeed,
              patch: source.patch,
              actorId: actor.identity.stableId,
            })
          : source.kind === "regional-alpine"
          ? projectCoreEcologyAlpineRidgeActivityAuthority({
              rootSeed,
              patch: source.patch,
              actorId: actor.identity.stableId,
            })
          : source.kind === "regional-habitat" || source.kind === "legacy-cohort"
          ? projectCoreEcologyActivityAuthority({
              rootSeed,
              root,
              sourceKind: source.kind,
              patch: source.patch,
              actorId: actor.identity.stableId,
            })
          : null,
        validate: (
          authority: unknown,
        ): authority is CoreEcologyActivityAuthorityReceipt => (
          runtimeCoreEcologyActivityAuthorityReceiptIsValid(
            source,
            actor,
            lineage.expectedProvenance,
            authority,
          )
        ),
      }));
    }
  }
  return receiptCache.project({ sourceKeys, requests });
}

type RuntimeCoreEcologyActivityAuthorityProvenance =
  | "breadth-habitat"
  | "legacy-habitat"
  | "regional-habitat"
  | null;

function runtimeCoreEcologyActivityAuthorityLineage(
  root: RegionalEcologyRootV1,
  source: RuntimeRegionalEcologyProjectedSource,
  actorId: string,
): Readonly<{
  expectedProvenance: RuntimeCoreEcologyActivityAuthorityProvenance;
  legacyCustodyKey: string | null;
  lineageKey: string;
}> | null {
  const derivation = source.patch.derivation;
  if (source.kind === "regional-habitat") {
    if (
      derivation.kind !== "regional-habitat-v1"
      && derivation.kind !== "regional-habitat-v1-with-adoption-suppression"
    ) return null;
    return Object.freeze({
      expectedProvenance: "regional-habitat" as const,
      legacyCustodyKey: null,
      lineageKey: derivation.kind === "regional-habitat-v1"
        ? derivation.habitat.derivationHash
        : hashCanonical([
            derivation.habitat.derivationHash,
            derivation.suppression,
          ]),
    });
  }
  if (source.kind === "legacy-cohort") {
    if (
      derivation.kind !== "legacy-cohort-v1"
      || root.adoption === null
      || root.legacyCohort === null
    ) return null;
    const disposition = root.adoption.actorDispositions.find((candidate) => (
      candidate.actorId === actorId
    ));
    if (disposition === undefined || disposition.disposition === "retired") return null;
    return Object.freeze({
      expectedProvenance: disposition.disposition === "redistributed"
        ? "regional-habitat" as const
        : "legacy-habitat" as const,
      legacyCustodyKey: hashCanonical(disposition),
      lineageKey: hashCanonical([
        derivation.adoptionTransactionId,
        derivation.rootSeedFingerprint,
        derivation.sourcePatchHash,
        root.adoption.transactionId,
        root.legacyCohort.sourcePatchHash,
      ]),
    });
  }
  if (source.kind === "regional-alpine") {
    return derivation.kind !== "regional-alpine-v1"
      ? null
      : Object.freeze({
          expectedProvenance: null,
          legacyCustodyKey: null,
          lineageKey: derivation.habitat.derivationHash,
        });
  }
  if (source.kind === "regional-polar-consumer-v1") {
    return derivation.kind !== "regional-polar-consumer-v1"
      ? null
      : Object.freeze({
          expectedProvenance: "regional-habitat" as const,
          legacyCustodyKey: null,
          lineageKey: derivation.habitat.derivationHash,
        });
  }
  if (source.kind === "regional-breadth-v1") {
    return derivation.kind !== "regional-breadth-v1"
      ? null
      : Object.freeze({
          expectedProvenance: "breadth-habitat" as const,
          legacyCustodyKey: null,
          lineageKey: derivation.habitat.derivationHash,
        });
  }
  return null;
}

function runtimeCoreEcologyActivityAuthorityReceiptIsValid(
  source: RuntimeRegionalEcologyProjectedSource,
  actor: CoreWildlifeActorState,
  expectedProvenance: RuntimeCoreEcologyActivityAuthorityProvenance,
  authority: unknown,
): authority is CoreEcologyActivityAuthorityReceipt {
  if (
    typeof authority !== "object"
    || authority === null
    || !("sourceKey" in authority)
    || authority.sourceKey !== source.sourceKey
    || !("actorId" in authority)
    || authority.actorId !== actor.identity.stableId
  ) return false;
  if (source.kind === "regional-alpine") {
    return actor.identity.species === "golden-eagle"
      && isTrustedCoreEcologyAlpineRidgeActivityAuthority(authority);
  }
  if (!isTrustedCoreEcologyActivityAuthority(authority)) return false;
  if (
    authority.species !== actor.identity.species
    || authority.provenance !== expectedProvenance
  ) return false;
  return source.kind !== "regional-polar-consumer-v1"
    || isTrustedCoreEcologyPolarConsumerActivityAuthority(authority);
}

type RuntimeRegionalEcologyProjectedSource =
  | Pick<
      RegionalEcologyProjectedResidentV1,
      "kind" | "patch" | "region" | "sourceKey"
    >
  | Pick<
      RegionalEcologyStateV2ProjectedAlpineResidentV1,
      "kind" | "patch" | "region" | "sourceKey"
    >
  | Pick<
      RegionalEcologyStateV3ProjectedPolarShoreResidentV1,
      "kind" | "patch" | "region" | "sourceKey"
    >
  | Pick<
      RegionalEcologyStateV4ProjectedColdShoreResidentV1,
      "kind" | "patch" | "region" | "sourceKey"
    >
  | Pick<
      RegionalEcologyStateV5ProjectedPolarConsumerResidentV1,
      "kind" | "patch" | "region" | "sourceKey"
    >
  | Pick<
      RegionalEcologyStateV6ProjectedBreadthResidentV1,
      "kind" | "patch" | "region" | "sourceKey"
    >;

function runtimeRegionalEcologyProjectedSources(
  projection: RegionalEcologyStateV6ActiveProjection,
): readonly RuntimeRegionalEcologyProjectedSource[] {
  return Object.freeze([
    ...projection.base.base.base.base.base.residents,
    ...projection.base.base.base.base.alpineResidents,
    ...projection.base.base.base.polarShoreResidents,
    ...projection.base.base.coldShoreResidents,
    ...projection.base.polarConsumerResidents,
    ...projection.breadthResidents,
  ]);
}

/**
 * Bounded presentation sidecar for directly visible expressive wildlife calls. It is a
 * projection of the already admitted materialized set, never a second wildlife
 * materializer or a source of simulation authority.
 */
function runtimeCoreWildlifeExpressionSources(
  projection: RegionalEcologyStateV6ActiveProjection,
  activeExpressions: readonly ActiveSituatedExpressionChannelPair[] = [],
): readonly CoreWildlifeExpressionSource[] {
  const seenActorIds = new Set<string>();
  const sources: CoreWildlifeExpressionSource[] = [];
  for (const { patch } of runtimeRegionalEcologyProjectedSources(projection)) {
    for (const population of patch.populations) {
      if (
        !isExpressiveAlarmSpecies(population.species)
        && population.species !== "domestic-cat"
        && population.species !== "marsh-fox"
      ) continue;
      for (const { actor, materialization } of population.members) {
        if (materialization !== "materialized") continue;
        if (seenActorIds.has(actor.identity.stableId)) {
          throw new Error("Wildlife expression projection found duplicate actor custody");
        }
        seenActorIds.add(actor.identity.stableId);
        const weatherCall = population.species === "domestic-cat"
          ? activeExpressions.find(({ event }) => (
              event.sourceActorId === actor.identity.stableId
              && event.meaning === "domestic-cat-rain-distress-call"
            ))?.event ?? null
          : null;
        let sourcePosition = actor.address.position;
        if (weatherCall !== null) {
          try {
            const delta = worldPositionDelta(weatherCall.position, actor.address.position);
            const maximumStepUnits = coreWildlifeMaximumStepUnits(
              "domestic-cat",
              "retreat",
            );
            if (
              delta.x * delta.x + delta.y * delta.y
                <= maximumStepUnits * maximumStepUnits
            ) sourcePosition = weatherCall.position;
          } catch {
            // A cross-world/tampered locus keeps the current body position so
            // downstream source authentication rejects the visible anchor.
          }
        }
        sources.push(Object.freeze({
          actorId: actor.identity.stableId,
          species: population.species,
          position: sourcePosition,
        }));
      }
    }
  }
  sources.sort((left, right) => compareText(left.actorId, right.actorId));
  if (sources.length > CORE_ECOLOGY_MAX_MATERIALIZED_ACTORS) {
    throw new Error("Wildlife expression projection exceeded materialization authority");
  }
  return Object.freeze(sources);
}

function runtimeMaterializedCoreActorIds(
  patch: CoreEcologyAggregatePatchState,
): readonly string[] {
  return Object.freeze(patch.populations
    .flatMap(({ members }) => members)
    .filter(({ materialization }) => materialization === "materialized")
    .map(({ actor }) => actor.identity.stableId)
    .sort(compareText));
}

function canonicalRuntimeRegionalEcologyStateV1(
  value: unknown,
  world: WorldState,
  bio0: Bio0EcologyState,
  economy: WorldView = createWorldView(world),
): RegionalEcologyStateV1 | null {
  return canonicalRegionalEcologyStateForWorld(value, {
    rootSeed: world.meta.rootSeed,
    completedTick: world.meta.completedTick,
    settlementHomeHabitat: deriveRuntimeCoreEcologyHabitat(world, bio0, economy),
  });
}

function canonicalRuntimeRegionalEcologyStateV2(
  value: unknown,
  world: WorldState,
  bio0: Bio0EcologyState,
  economy: WorldView = createWorldView(world),
): RegionalEcologyStateV2 | null {
  return canonicalRegionalEcologyStateV2ForWorld(value, {
    rootSeed: world.meta.rootSeed,
    completedTick: world.meta.completedTick,
    settlementHomeHabitat: deriveRuntimeCoreEcologyHabitat(world, bio0, economy),
  });
}

function canonicalRuntimeRegionalEcologyState(
  value: unknown,
  world: WorldState,
  bio0: Bio0EcologyState,
  economy: WorldView = createWorldView(world),
  requireFreshAlarmLoci = true,
): RegionalEcologyStateV6 | null {
  const settlementHomeHabitat = deriveRuntimeCoreEcologyHabitat(
    world,
    bio0,
    economy,
  );
  const state = runtimeRegionalEcologyWorldBindingMemo.canonicalize(value, {
    rootSeed: world.meta.rootSeed,
    completedTick: world.meta.completedTick,
    settlementHomeHabitat,
  });
  return state !== null && runtimeCommittedAlarmLociMatchStoredActors(
    state,
    requireFreshAlarmLoci,
  )
    ? state
    : null;
}

/**
 * Authenticates only durable, unprojected ecology custody. Active projection
 * may lawfully rematerialize a body at the same tick while the earlier call
 * remains at its committed locus; that transient view must not be subjected
 * to this stored-state invariant.
 */
function runtimeCommittedAlarmLociMatchStoredActors(
  state: RegionalEcologyStateV6,
  requireFreshLocus = true,
): boolean {
  const sources = regionalEcologyStateV6ActiveSourcePatches(state);
  if (sources === null) return false;
  for (const { patch } of sources) {
    if (!runtimePatchCommittedAlarmLociMatchStoredActors(patch, requireFreshLocus)) {
      return false;
    }
  }
  return true;
}

/**
 * Validates one durable patch before any active projection can lawfully move a
 * body away from its same-tick call. Older retained events intentionally keep
 * their historical locus and therefore are never compared with a later body.
 */
function runtimePatchCommittedAlarmLociMatchStoredActors(
  patch: CoreEcologyAggregatePatchState,
  requireFreshLocus: boolean,
): boolean {
  for (const population of patch.populations) {
    for (const { actor } of population.members) {
      if (
        actor.updatedAtTick !== patch.updatedAtTick
        || actor.intent.kind !== "alarm"
        || actor.intent.enteredAtTick !== actor.updatedAtTick
      ) continue;
      const eventId = `${actor.identity.stableId}:e:${actor.updatedAtTick.toString(36)}:alarm`;
      const matching = actor.memories.filter((memory) => memory.eventId === eventId);
      const memory = matching[0];
      if (
        matching.length !== 1
        || memory === undefined
        || memory.kind !== "alarm"
        || memory.atTick !== actor.updatedAtTick
        || memory.observationId !== actor.intent.focusObservationId
      ) return false;
      const locus = coreWildlifeAlarmEventLocus(actor, eventId);
      if (locus === null) {
        if (requireFreshLocus) return false;
        continue;
      }
      if (!sameRuntimeWorldPosition(locus, actor.address.position)) return false;
    }
  }
  return true;
}

/**
 * Every physical patch copy retained by the composite save, including dormant
 * sparse-root deviations. Active snapshots may duplicate root custody; both
 * byte copies are validated because either can later become authoritative.
 */
function runtimeRegionalEcologyAllStoredPatches(
  state: RegionalEcologyStateV6,
): readonly CoreEcologyAggregatePatchState[] {
  const v5 = state.base;
  const v4 = v5.base;
  const v3 = v4.base;
  const v2 = v3.base;
  const v1 = v2.base;
  return Object.freeze([
    v1.settlementHome.patch,
    ...v1.activeResidents.map(({ patch }) => patch),
    ...v1.root.regions.flatMap(({ residentPatch }) => (
      residentPatch === null ? [] : [residentPatch]
    )),
    ...(v1.root.legacyCohort === null ? [] : [v1.root.legacyCohort.sourcePatch]),
    ...v2.alpineActiveResidents.map(({ patch }) => patch),
    ...v2.alpineRoot.regions.map(({ residentPatch }) => residentPatch),
    ...v3.polarShoreActiveResidents.map(({ patch }) => patch),
    ...v3.polarShoreRoot.regions.map(({ residentPatch }) => residentPatch),
    ...v4.coldShoreActiveResidents.map(({ patch }) => patch),
    ...v4.coldShoreRoot.regions.map(({ residentPatch }) => residentPatch),
    ...v5.polarConsumerActiveResidents.map(({ patch }) => patch),
    ...v5.polarConsumerRoot.regions.map(({ residentPatch }) => residentPatch),
    ...state.breadthActiveResidents.map(({ patch }) => patch),
    ...state.breadthRoot.regions.map(({ residentPatch }) => residentPatch),
  ]);
}

/** Full sparse-custody validation belongs only at load/save boundaries. */
function runtimeAllStoredAlarmLociMatchActors(
  state: RegionalEcologyStateV6,
): boolean {
  return runtimeRegionalEcologyAllStoredPatches(state).every((patch) => (
    runtimePatchCommittedAlarmLociMatchStoredActors(patch, false)
  ));
}

/**
 * Adopts only the released pre-v38 representation: a current same-tick alarm
 * had no retained locus, and delayed code used its durable post-locomotion body
 * address. The active composite owner performs the one-time rewrite before any
 * projection is consumed; the stored body, never a rematerialized address,
 * supplies the historical locus.
 */
function adoptLegacyRegionalAlarmEventLoci(
  state: RegionalEcologyStateV6,
): RegionalEcologyStateV6 | null {
  const storedSources = regionalEcologyStateV6ActiveSourcePatches(state);
  if (storedSources === null) return null;
  const storedBySource = new Map(storedSources.map(({ sourceKey, patch }) => (
    [sourceKey, patch] as const
  )));
  if (storedBySource.size !== storedSources.length) return null;
  const needsAdoption = storedSources.some(({ patch }) => patch.populations.some(
    ({ members }) => members.some(({ actor }) => {
      if (
        actor.updatedAtTick !== patch.updatedAtTick
        || actor.intent.kind !== "alarm"
        || actor.intent.enteredAtTick !== actor.updatedAtTick
      ) return false;
      const eventId = `${actor.identity.stableId}:e:${actor.updatedAtTick.toString(36)}:alarm`;
      return coreWildlifeAlarmEventLocus(actor, eventId) === null;
    }),
  ));
  if (!needsAdoption) return state;
  const adoptedBySource = new Map<string, CoreEcologyAggregatePatchState>();
  let changed = false;
  for (const { sourceKey, patch } of storedSources) {
    let adopted = patch;
    for (const population of patch.populations) {
      for (const { actor: storedActor } of population.members) {
        const adoptedActor = adoptLegacyCoreWildlifeAlarmEventLocus(
          storedActor,
          storedActor,
        );
        if (adoptedActor === null) return null;
        if (stableStringify(adoptedActor) !== stableStringify(storedActor)) {
          adopted = replaceCoreEcologyAggregatePatchActor(adopted, adoptedActor);
          changed = true;
        }
      }
    }
    adoptedBySource.set(sourceKey, adopted);
  }
  if (!changed || adoptedBySource.size !== storedSources.length) {
    return changed ? null : state;
  }

  const consumed = new Set<string>();
  const adoptedPatch = (
    sourceKey: string,
    fallback: CoreEcologyAggregatePatchState,
  ): CoreEcologyAggregatePatchState => {
    const adopted = adoptedBySource.get(sourceKey);
    if (adopted === undefined) return fallback;
    consumed.add(sourceKey);
    return adopted;
  };
  try {
    const v5 = state.base;
    const v4 = v5.base;
    const v3 = v4.base;
    const v2 = v3.base;
    const v1 = v2.base;
    const adoptedV1 = createRegionalEcologyState({
      root: v1.root,
      settlementHome: {
        sourceKey: v1.settlementHome.sourceKey,
        patch: adoptedPatch(
          v1.settlementHome.sourceKey,
          v1.settlementHome.patch,
        ),
      },
      activeRegions: v1.activeRegions,
      activeResidents: v1.activeResidents.map(({ kind, sourceKey, patch }) => {
        if (kind === "settlement-home") {
          throw new RangeError("Regional ecology home cannot occupy the active-resident list");
        }
        return {
          kind,
          sourceKey,
          patch: adoptedPatch(sourceKey, patch),
        };
      }),
    });
    const adoptedV2 = createRegionalEcologyStateV2({
      base: adoptedV1,
      alpineRoot: v2.alpineRoot,
      alpineActiveResidents: v2.alpineActiveResidents.map(({ sourceKey, patch }) => ({
        sourceKey,
        patch: adoptedPatch(sourceKey, patch),
      })),
      adoption: v2.adoption,
    });
    const adoptedV3 = createRegionalEcologyStateV3({
      base: adoptedV2,
      polarShoreRoot: v3.polarShoreRoot,
      polarShoreActiveResidents: v3.polarShoreActiveResidents.map(({ sourceKey, patch }) => ({
        sourceKey,
        patch: adoptedPatch(sourceKey, patch),
      })),
      adoption: v3.adoption,
    });
    const adoptedV4 = createRegionalEcologyStateV4({
      base: adoptedV3,
      coldShoreRoot: v4.coldShoreRoot,
      coldShoreActiveResidents: v4.coldShoreActiveResidents.map(({ sourceKey, patch }) => ({
        sourceKey,
        patch: adoptedPatch(sourceKey, patch),
      })),
      adoption: v4.adoption,
    });
    const adoptedV5 = createRegionalEcologyStateV5({
      base: adoptedV4,
      polarConsumerRoot: v5.polarConsumerRoot,
      polarConsumerActiveResidents: v5.polarConsumerActiveResidents.map(({
        sourceKey,
        patch,
      }) => ({
        sourceKey,
        patch: adoptedPatch(sourceKey, patch),
      })),
      adoption: v5.adoption,
    });
    const adoptedV6 = createRegionalEcologyStateV6({
      base: adoptedV5,
      breadthRoot: state.breadthRoot,
      breadthActiveResidents: state.breadthActiveResidents.map(({ sourceKey, patch }) => ({
        sourceKey,
        patch: adoptedPatch(sourceKey, patch),
      })),
      adoption: state.adoption,
    });
    return consumed.size === adoptedBySource.size ? adoptedV6 : null;
  } catch {
    return null;
  }
}

const runtimeRegionalEcologyWorldBindingMemo =
  createRuntimeRegionalEcologyWorldBindingMemo<
    RegionalEcologyStateV6,
    CoreEcologyRegionalPredatorHabitatAssemblage
  >({
    validator: canonicalRegionalEcologyStateV6ForWorld,
    completedTickOf: (state) => state.updatedAtTick,
    isTrustedCommittedTransition:
      isTrustedRegionalEcologyStateV6ActiveCommitTransition,
  });

function canonicalRuntimeRegionalEcologyCommittedTransition(
  previous: RegionalEcologyStateV6,
  value: unknown,
  world: WorldState,
  bio0: Bio0EcologyState,
  economy: WorldView,
): RegionalEcologyStateV6 | null {
  const state = runtimeRegionalEcologyWorldBindingMemo.canonicalizeCommittedTransition(
    previous,
    value,
    {
      rootSeed: world.meta.rootSeed,
      completedTick: world.meta.completedTick,
      settlementHomeHabitat: deriveRuntimeCoreEcologyHabitat(world, bio0, economy),
    },
  );
  return state !== null && runtimeCommittedAlarmLociMatchStoredActors(state)
    ? state
    : null;
}

/**
 * Exchanges only the bounded hot neighborhood. Before an owner leaves memory,
 * any changed regional patch is written into the sparse root ledger; pristine
 * seeded baselines therefore cost no durable bytes merely because the player
 * crossed them.
 */
function rebaseRuntimeRegionalEcologyState(
  value: RegionalEcologyStateV6,
  world: WorldState,
  bio0: Bio0EcologyState,
  regionalView: WorldView,
  economy: WorldView = createWorldView(world),
): RegionalEcologyStateV6 {
  const prior = canonicalRuntimeRegionalEcologyState(value, world, bio0, economy);
  if (prior === null) {
    throw new Error("Regional ecology could not authenticate before a window exchange");
  }
  // V1 owns the canonical ordering (lexicographic persistent region keys),
  // while the spatial view enumerates row-major. Normalize the tiny bounded
  // owner list before deciding whether this presentation-frame movement
  // actually changed ecology storage custody.
  const activeRegions = orderRuntimeRegionalEcologyActiveRegions(
    regionalStorageRegionsInView(regionalView),
  );
  const reusable = reuseAuthenticatedRuntimeRegionalEcologyState(
    prior,
    prior.base.base.base.base.base.activeRegions,
    activeRegions,
  );
  if (reusable !== null) return reusable;
  const desiredRegionKeys = new Set(activeRegions.map(regionKey));
  let root = prior.base.base.base.base.base.root;
  for (const resident of prior.base.base.base.base.base.activeResidents) {
    if (
      resident.kind !== "regional-habitat"
      || desiredRegionKeys.has(regionKey(resident.region))
    ) continue;
    root = putRegionalEcologyResidentDeviation(root, {
      rootSeed: world.meta.rootSeed,
      patch: resident.patch,
    });
  }

  const requiredRegionalResidents = regionalEcologyRegionalResidentsForActiveRegions(
    root,
    world.meta.rootSeed,
    activeRegions,
  );
  if (requiredRegionalResidents === null) {
    throw new Error("Regional ecology entrants could not be derived from physical residence");
  }
  const retainedBySource = new Map(prior.base.base.base.base.base.activeResidents
    .filter(({ kind }) => kind === "regional-habitat")
    .map((resident) => [resident.sourceKey, resident] as const));
  const activeResidents: RegionalEcologyActiveResidentInput[] = requiredRegionalResidents.map(
    (entrant) => {
      const retained = retainedBySource.get(entrant.sourceKey);
      return {
        kind: "regional-habitat" as const,
        sourceKey: entrant.sourceKey,
        // Preserve the already-authenticated live snapshot whenever this owner
        // remains required. Root derivation decides eligibility; it never
        // transfers identities merely because residence crossed a seam.
        patch: retained?.patch ?? entrant.patch,
      };
    },
  );
  for (const legacy of prior.base.base.base.base.base.activeResidents.filter(({ kind }) => kind === "legacy-cohort")) {
    activeResidents.push({
      kind: "legacy-cohort",
      sourceKey: legacy.sourceKey,
      patch: legacy.patch,
    });
  }
  const next = replaceRegionalEcologyStateV6ActiveState(prior, {
    expectedIntegrity: prior.integrity,
    base: {
      expectedIntegrity: prior.base.integrity,
      base: {
        expectedIntegrity: prior.base.base.integrity,
        base: {
          expectedIntegrity: prior.base.base.base.integrity,
          base: {
            expectedIntegrity: prior.base.base.base.base.integrity,
            base: {
              expectedIntegrity: prior.base.base.base.base.base.integrity,
              rootSeed: world.meta.rootSeed,
              root,
              settlementHome: {
                sourceKey: prior.base.base.base.base.base.settlementHome.sourceKey,
                patch: prior.base.base.base.base.base.settlementHome.patch,
              },
              activeRegions,
              activeResidents,
            },
          },
        },
      },
    },
  });
  // A dormant deviation migrated from an older save may first enter active
  // custody here. Bind its historically missing same-tick locus from the
  // durable stored body before any rematerialized address can be consumed.
  const adopted = adoptLegacyRegionalAlarmEventLoci(next);
  const canonical = adopted === null
    ? null
    : canonicalRuntimeRegionalEcologyState(adopted, world, bio0, economy);
  if (canonical === null) {
    throw new Error("Regional ecology window exchange failed its world binding");
  }
  return canonical;
}

function runtimeRegionalEcologyActor(
  projection: RegionalEcologyStateV6ActiveProjection,
  target: RuntimeCoreWildlifeTarget,
): CoreWildlifeActorState | null {
  const matches = runtimeRegionalEcologyProjectedSources(projection)
    .flatMap(({ patch }) => {
    const actor = selectedCoreEcologyActor(patch, target);
    return actor === null ? [] : [actor];
    });
  if (matches.length > 1) {
    throw new Error("Selected wildlife identity has multiple regional owners");
  }
  return matches[0] ?? null;
}

/** Frozen Alpha-30 v10 constructor used only to authenticate and extend v23 saves. */
function createRuntimeRegionalUplandCoreEcology(
  world: WorldState,
  bio0: Bio0EcologyState,
  economy: WorldView = createWorldView(world),
): CoreEcologyAggregatePatchState {
  const habitat = deriveRuntimeRegionalUplandCoreEcologyHabitat(world, bio0, economy);
  const groups = createRuntimeCoreEcologyGroups(world, habitat);
  let patch = createCoreEcologyAggregatePatch({
    seed: world.meta.rootSeed,
    patchKey: CORE_ECOLOGY_PATCH_KEY,
    originRegion: habitat.originRegion,
    tick: world.meta.completedTick,
    derivation: { kind: "habitat-v10", habitat },
    groups,
    populations: habitat.populations
      .filter(({ populationUnits, representation }) => (
        populationUnits > 0
        && representation === "individual-representatives"
      ))
      .filter(({ species }) => coreEcologySpeciesCanOwnActorAddress(species))
      .map((population) => ({
        species: population.species,
        populationKey: population.populationKey,
        populationSize: population.populationUnits,
        members: population.allocations.map((allocation) => ({
          populationOrdinal: allocation.allocationOrdinal,
          representedUnits: allocation.representedUnits,
          position: allocation.position,
          materialization: "coarse" as const,
        })),
      })),
  });
  const initialMaterialization = setCoreEcologyMaterializationForWindow(
    patch,
    {
      origin: (() => {
        const regionOrigin = regionLocalToGlobalTile(habitat.originRegion, 0, 0);
        return {
          x: regionOrigin.x - Math.trunc((REGIONAL_TRAVEL_COLUMNS - WORLD_WIDTH) / 2),
          y: regionOrigin.y - Math.trunc((REGIONAL_TRAVEL_ROWS - WORLD_HEIGHT) / 2),
        };
      })(),
      terrain: { width: REGIONAL_TRAVEL_COLUMNS, height: REGIONAL_TRAVEL_ROWS },
    },
    world.meta.completedTick,
  );
  if (initialMaterialization === null) {
    throw new Error("Initial tidal-web materialization failed validation");
  }
  patch = initialMaterialization;
  const bearMember = patch.populations
    .find(({ species }) => species === "black-bear")
    ?.members[0];
  if (bearMember !== undefined) {
    const hungryBear = replaceCoreWildlifeActorPhysiology(bearMember.actor, {
      atTick: world.meta.completedTick,
      needs: { ...bearMember.actor.needs, hunger: Math.max(680_000, bearMember.actor.needs.hunger) },
      condition: bearMember.actor.condition,
    });
    patch = replaceCoreEcologyAggregatePatchActor(patch, hungryBear);
  }
  const tidal = stepCoreEcologyTidalTable(patch, {
    atTick: world.meta.completedTick,
  });
  if (tidal === null) throw new Error("Initial tidal ecology projection failed validation");
  const initialized = initializeRuntimeTidalActivityActor(
    tidal.patch,
    tidal.projection,
    world.meta.completedTick,
  );
  if (initialized === null) throw new Error("Initial tidal actor placement failed validation");
  const waterfowlInitialized = initializeRuntimeWaterfowlActivityActor(
    initialized,
    world.meta.completedTick,
    compatibilityClearActivityWeather(world.meta.completedTick),
  );
  if (waterfowlInitialized === null) {
    throw new Error("Initial waterfowl placement failed validation");
  }
  const tidalWebInitialized = initializeRuntimeTidalWebActivityActor(
    waterfowlInitialized,
    world.meta.completedTick,
  );
  if (tidalWebInitialized === null) {
    throw new Error("Initial tidal-web activity placement failed validation");
  }
  return tidalWebInitialized;
}

